import XCTest
@testable import Mew
final class AppTests:XCTestCase {
    func testMultipageArabicPDF() { var h=Household();h.accounts=[Account(id:"cash",name:"نقد")];h.prefs.trackingStart="2020-01-01";for i in 0..<200{h.transactions.append(Transaction(id:"row-\(i)",type:.expense,amount:100,date:"2026-01-01",accountId:"cash",categoryId:"expense-0",note:"ملاحظة عربية"))};let bytes=PDFReport.make(h,Finance.cycle("2026-01-01",day:1));let provider=CGDataProvider(data:bytes as CFData)!;let pdf=CGPDFDocument(provider)!;XCTAssertGreaterThan(pdf.numberOfPages,1);XCTAssertEqual(pdf.page(at:1)?.getBoxRect(.mediaBox).width,595) }
    @MainActor func testStoreCommitAndReload() async throws { let store=Store();await store.load();guard var h=store.data else{XCTFail("load");return};if !h.prefs.ready {h.accounts=[Account(id:"test-cash",name:"اختبار")];h.prefs.ready=true;h.prefs.trackingStart="2020-01-01";h.prefs.defaultAccount="test-cash";try await store.repository!.save(h);await store.load()};let id=uid();let t=Transaction(id:id,type:.expense,amount:4321,accountId:h.accounts[0].id,categoryId:"expense-0");let saved=await store.save(t);XCTAssertTrue(saved);await store.load();XCTAssertEqual(store.data?.transactions.first{$0.id==id}?.amount,4321);await store.delete(t);XCTAssertFalse(store.data!.transactions.contains{$0.id==id});await store.undoDelete();XCTAssertTrue(store.data!.transactions.contains{$0.id==id}) }
}
